"""The rule tables in RULES.md match the YAML rules (generated by `rules list --markdown`);
README.md and docs/ keep their shared scope paragraph and working links."""

import re
from pathlib import Path

import pytest

from helpers import builtin_rules
from repovet.cli import EXIT_OK, main

RULES = Path(__file__).parent.parent / "RULES.md"
START = "<!-- rules-table:start -->"
END = "<!-- rules-table:end -->"


def test_rule_tables_are_current(capsys: pytest.CaptureFixture[str]) -> None:
    assert main(["rules", "list", "--markdown"]) == EXIT_OK
    generated = capsys.readouterr().out
    text = RULES.read_text(encoding="utf-8")
    assert text.count(START) == 1
    assert text.count(END) == 1
    table = text.split(START)[1].split(END)[0]
    assert table.strip() == generated.strip(), (
        "RULES.md is out of date; regenerate the tables with `uv run repovet rules list --markdown`"
    )


def test_markdown_lists_every_rule_once(capsys: pytest.CaptureFixture[str]) -> None:
    main(["rules", "list", "--markdown"])
    rows = [line for line in capsys.readouterr().out.splitlines() if line.startswith("| RC-")]
    assert sorted(row.split(" | ")[0][2:] for row in rows) == sorted(
        rule.id for rule in builtin_rules().rules
    )
    main(["rules", "list", "--markdown", "--area", "agents"])
    out = capsys.readouterr().out
    assert "RC-AGENT-001" in out
    assert "RC-AUTO-" not in out


README = Path(__file__).parent.parent / "README.md"
DOCS = Path(__file__).parent.parent / "docs"
SCOPE_START = "<!-- scope:start -->"
SCOPE_END = "<!-- scope:end -->"
_LINK = re.compile(r"\]\(([^)\s]+)\)")
_FENCE = re.compile(r"^\s*(```|~~~)")


def _scope(text: str) -> str:
    assert text.count(SCOPE_START) == 1 and text.count(SCOPE_END) == 1
    return text.split(SCOPE_START)[1].split(SCOPE_END, maxsplit=1)[0].strip()


def _anchors(text: str) -> set[str]:
    """GitHub heading anchors of a Markdown file (headings in code blocks excluded)."""
    anchors, fenced = set(), False
    for line in text.splitlines():
        if _FENCE.match(line):
            fenced = not fenced
        elif not fenced and line.startswith("#"):
            title = line.lstrip("#").strip().lower()
            anchors.add(re.sub(r"[^\w\- ]", "", title).replace(" ", "-"))
    return anchors


def _links(text: str) -> list[str]:
    links, fenced = [], False
    for line in text.splitlines():
        if _FENCE.match(line):
            fenced = not fenced
        elif not fenced:
            links += _LINK.findall(line)
    return links


def test_scope_paragraph_is_the_same_in_readme_and_limits() -> None:
    readme = _scope(README.read_text(encoding="utf-8"))
    assert readme == _scope((DOCS / "limits.md").read_text(encoding="utf-8"))
    for tool in ("pip-audit", "npm audit", "OSV-Scanner"):
        assert tool in readme


def test_readme_links_work_on_pypi() -> None:
    """PyPI renders README.md without the repository, so every link must be absolute."""
    links = _links(README.read_text(encoding="utf-8"))
    assert links
    relative = [link for link in links if not link.startswith("https://")]
    assert relative == [], f"use absolute GitHub URLs in README.md: {relative}"


@pytest.mark.parametrize("page", sorted(DOCS.glob("*.md")), ids=lambda p: p.name)
def test_relative_links_in_docs_resolve(page: Path) -> None:
    for link in _links(page.read_text(encoding="utf-8")):
        if re.match(r"[a-z]+:", link):
            continue
        target, _, anchor = link.partition("#")
        path = (page.parent / target).resolve() if target else page
        assert path.is_file(), f"{page.name}: broken link {link}"
        if anchor and path.suffix == ".md":
            assert anchor in _anchors(path.read_text(encoding="utf-8")), (
                f"{page.name}: missing anchor {link}"
            )
